/* Whether a report line containing prefix also contains needle. */
static int coref_line(const char *report, const char *prefix, const char *needle)
{
    for (const char *line = report; line && *line;) {
        const char *end = strchr(line, '\n');
        size_t length = end ? (size_t)(end - line) : strlen(line);
        char *copy = malloc(length + 1);
        if (!copy) return 0;
        memcpy(copy, line, length); copy[length] = 0;
        int found = strstr(copy, prefix) && strstr(copy, needle);
        free(copy);
        if (found) return 1;
        line = end ? end + 1 : NULL;
    }
    return 0;
}
#define COREF_CATCHER(unique, name) "{\"entityDef\":{\"className\":\"idProjectile_Boomerang\",\"inherit\":"     "\"inlinestock/boomerang\",\"name\":\"\",\"state\":{\"edit\":{\"allowablePickups\":{\"num\":1,\"item[0]\":\"" name     "\"}}},\"targetType\":\"idDeclEntityDef\",\"~type\":\"idDeclEntityDef\",\"~version\":26},\"uniqueId\":" unique "}"
