        char *bound = NULL, *document = NULL, *derived = NULL, *report = NULL;
        size_t bound_length = 0, document_length = strlen(json), derived_length = 0, count = 99;
        sh_package_occurrence_snapshot *ownership = NULL; sh_mpkg_used *used = NULL;
        int present = 0;
