    const sh_package_provenance *recaptured = ownership ? sh_package_occurrence_provenance(ownership) : NULL;
    int projected = 0;
    for (size_t i = 0; recaptured && i < recaptured->use_count; i++)
        projected |= recaptured->uses[i].reference && strstr(recaptured->uses[i].reference, "damageType") != NULL;
