        CHECK(saved && sh_map_provenance_read(saved, saved_length, &kept_carried, &kept_present, kept_error, sizeof(kept_error)) && kept_present);
        kept_sources = sh_package_sources_scan(data, kept_error, sizeof(kept_error));
