            reopened = kept_plan ? sh_package_map_plan_rebind(kept_plan, &kept_carried, saved, saved_length,
                &reopened_length, kept_error, sizeof(kept_error)) : NULL;
            if (!reopened) fprintf(stderr, "m108 kept reopen: %s\n", kept_error);
            CHECK(reopened != NULL);
            if (reopened) m109_native_read(sh_package_map_plan_compilation(kept_plan), reopened, reopened_length, &read);
            else memset(&read, 0, sizeof(read));
