/* The elements of a document's entities array (string-aware): head is the
 * offset after "entities":[ and tail that of its closing bracket. */
typedef struct m110_entities { size_t head, tail, count, at[32], length[32]; } m110_entities;
static int m110_split(const char *json, size_t length, m110_entities *out)
{
    const char *array = m109_find(json, length, "\"entities\":[");
    int depth = 0, string = 0;
    memset(out, 0, sizeof(*out));
    if (!array) return 0;
    out->head = (size_t)(array - json);
    for (size_t i = out->head, begin = 0; i < length; i++) {
        char c = json[i];
        if (string) { if (c == '\\') i++; else if (c == '"') string = 0; continue; }
        if (c == '"') string = 1;
        else if (c == '{' || c == '[') { if (!depth++) begin = i; }
        else if (c == '}' || c == ']') {
            if (!depth) { out->tail = i; return 1; }
            if (!--depth) {
                if (out->count == 32) return 0;
                out->at[out->count] = begin; out->length[out->count++] = i + 1 - begin;
            }
        }
    }
    return 0;
}
/* A copy's bytes with its inherit value and any damageType member set aside:
 * what a variant's retarget, fold, materialization or projection may change. */
static int m110_copy_core(const char *entity, size_t length, char *out, size_t capacity)
{
    static const char inherit[] = "\"inherit\":\"", damage[] = "\"damageType\":\"";
    size_t n = 0;
    for (size_t i = 0; i < length;) {
        if (i + sizeof(inherit) - 1 <= length && !memcmp(entity + i, inherit, sizeof(inherit) - 1)) {
            if (n + sizeof(inherit) >= capacity) return 0;
            memcpy(out + n, inherit, sizeof(inherit) - 1); n += sizeof(inherit) - 1; i += sizeof(inherit) - 1;
            while (i < length && entity[i] != '"') i++;
            continue;
        }
        if (i + sizeof(damage) - 1 <= length && !memcmp(entity + i, damage, sizeof(damage) - 1)) {
            for (i += sizeof(damage) - 1; i < length && entity[i] != '"'; i++) {}
            if (++i < length && entity[i] == ',') i++;
            else if (n && out[n - 1] == ',') n--;
            continue;
        }
        if (n + 1 >= capacity) return 0;
        out[n++] = entity[i++];
    }
    out[n] = 0; return 1;
}
/* 1 when a stage kept every byte unrelated to the copies: the document outside
 * its entities array, every stock entity and, with cores, each copy's bytes
 * apart from its inherit value and damageType member. */
static int m110_unrelated_kept(const char *stage, const char *in, size_t in_length, const char *out, size_t out_length,
    size_t stock, int cores)
{
    static char x[16384], y[16384];
    m110_entities a, b;
    int ok = in && out && m110_split(in, in_length, &a) && m110_split(out, out_length, &b) && a.count == b.count &&
        a.head == b.head && !memcmp(in, out, a.head) && in_length - a.tail == out_length - b.tail &&
        !memcmp(in + a.tail, out + b.tail, in_length - a.tail);
    if (!ok) { fprintf(stderr, "m110 %s: the document around its entities changed\n", stage); return 0; }
    for (size_t i = 0; i < a.count; i++) {
        if (i < stock ? a.length[i] == b.length[i] && !memcmp(in + a.at[i], out + b.at[i], a.length[i]) :
            !cores || (m110_copy_core(in + a.at[i], a.length[i], x, sizeof(x)) &&
            m110_copy_core(out + b.at[i], b.length[i], y, sizeof(y)) && !strcmp(x, y))) continue;
        fprintf(stderr, "m110 %s: entity %zu changed\n  in  %.*s\n  out %.*s\n", stage, i, (int)a.length[i], in + a.at[i],
            (int)b.length[i], out + b.at[i]);
        return 0;
    }
    return 1;
}
/* The document with the inherits of entities first..first+3 (P, N, T, the
 * deeper copy) replaced where names gives one. */
static char *m110_named(const char *json, size_t first, const char *const names[4])
{
    static const char key[] = "\"inherit\":\"";
    size_t used = 0;
    char *out = malloc(strlen(json) + 4 * 128 + 1);
    const char *at = json, *next;
    if (!out) return NULL;
    for (size_t i = 0; (next = strstr(at, key)) != NULL; i++) {
        next += sizeof(key) - 1;
        const char *end = strchr(next, '"'), *name = i >= first && i < first + 4 ? names[i - first] : NULL;
        if (!end || (name && strlen(name) > 127)) { free(out); return NULL; }
        memcpy(out + used, at, (size_t)(next - at)); used += (size_t)(next - at);
        if (!name) name = next;
        size_t n = name == next ? (size_t)(end - next) : strlen(name);
        memcpy(out + used, name, n); used += n; at = end;
    }
    memcpy(out + used, at, strlen(at) + 1);
    return out;
}
static const char *m110_nth(const char *text, const char *pattern, size_t nth)
{
    const char *at = text;
    for (size_t i = 0; at && (at = strstr(at, pattern)) != NULL && i < nth; i++) at++;
    return at;
}
