    plan_d = saved_d ? sh_package_runtime_prepare_map_document(data, map_c, &kept_d, rows_c, 2, saved_d, saved_d_length,
        error, sizeof(error)) : NULL;
    reopened_d = plan_d ? sh_package_map_plan_rebind(plan_d, &kept_d, saved_d, saved_d_length, &reopened_d_length, error,
        sizeof(error)) : NULL;
