    sh_package_occurrence_release(world_p); sh_package_occurrence_release(document); sh_package_occurrence_release(save);
    sh_package_occurrence_release(derived_ownership); sh_package_occurrence_release(world_c); sh_package_occurrence_release(save_c);
    sh_mpkg_used_free(used); sh_mpkg_used_free(derived_used);
