    expect_current(dependency, "health = 22"); expect_current(source_root_path, NULL);
    sh_package_occurrence_release(direct); direct = NULL;
    CHECK(sh_package_runtime_select_map(NULL, 0, NULL, error, sizeof(error)));
    state.after = 0;
