    state.recovery_fail = 0;
    CHECK(sh_package_runtime_complete_occurrence_recovery(&state));
    CHECK(sh_package_runtime_ready() && sh_package_runtime_admission_ready());
    CHECK(!sh_package_runtime_complete_occurrence_recovery(&state));
    state.finalize_fail = 0;
