        snprintf(names[i], sizeof(names[i]), "%.*s", (int)(strlen(name) - 5), name);
        r->engine_path = (char *)rows[i].path; r->original_path = (char *)rows[i].original;
        r->type = "snapeditorentitydef"; r->name = names[i]; r->source = SIZE_MAX;
        r->body = (unsigned char *)rows[i].body; r->body_length = strlen(rows[i].body);
        if (!strcmp(names[i], "zz/label")) CHECK(sh_package_owners_add(&r->owners, 0)); /* a change, not the original */
