        CHECK(!sh_package_runtime_exposure_kept("zz/label", kept, sizeof(kept)) && !*kept); /* a change under its own name */
        CHECK(!sh_package_runtime_exposure_kept("smp/c1", kept, sizeof(kept)) && !*kept);   /* a distinct exposure */
        CHECK(!sh_package_runtime_exposure_kept("xp/key", kept, 6) && !*kept);              /* too small: nothing */
        CHECK(!sh_package_runtime_exposure_kept(NULL, kept, sizeof(kept)));
