        CHECK(sh_package_runtime_test_publish_exposure(&compiled, NULL, &sources, exposure_baseline, NULL) == 1);
        const char *b1 = sh_package_runtime_test_exposure_reason("smp/b1"), *zz = sh_package_runtime_test_exposure_reason("zz/label");
        const char *key = sh_package_runtime_test_exposure_reason("xp/key");
        CHECK(b1 && !strcmp(b1, path) && zz && !strcmp(zz, path) && key && !strcmp(key, change));
        CHECK(!sh_package_runtime_test_exposure_reason("smp/z1"));
