    sh_package_runtime_test_editor_rows(exposure_rows, sizeof(exposure_rows) / sizeof(*exposure_rows));
    const sh_strids_palette_entry *entries = NULL; size_t count = 0;
    CHECK(sh_package_runtime_test_palette_of(&compiled, &entries, &count) == 1);
    CHECK(roster_find(entries, count, "smp/a1") && roster_find(entries, count, "smp/c1") &&
        roster_find(entries, count, "smp/e1") && roster_find(entries, count, "smp/g1") &&
        roster_find(entries, count, "smp/l1") && roster_find(entries, count, "smp/n1") &&
        roster_find(entries, count, "smp/h1") && roster_find(entries, count, "smp/s1"));
    CHECK(!roster_find(entries, count, "xp/key") && !roster_find(entries, count, "smp/b1") &&
        !roster_find(entries, count, "smp/d1") && !roster_find(entries, count, "smp/f1") &&
        !roster_find(entries, count, "xp/lamp") && !roster_find(entries, count, "smp/n2") &&
        !roster_find(entries, count, "aa/stone"));
    /* This unpublished compilation's own selection has no bindings: the lower row path keeps Birch's icon row. */
    CHECK(roster_find(entries, count, "smp/z1") && !roster_find(entries, count, "zz/label"));
    sh_package_runtime_test_editor_rows(NULL, 0);
