/* B2 in the per-input report (README: show source and exposures). Two
 * packages republish the shipped base row with only their own label text: one
 * equal exposure with the shipped row, kept in the pickers by the earlier
 * package's row. Each input stays served; its report names the editor row,
 * whether the pickers keep it or leave it out, and why. A third package's
 * entityDef, and the parent it inherits, are exposed by its own two editor
 * rows, which no equal exposure touches. */
static const char *input_row_name(const char *text, const char *after, char *name, size_t capacity)
{
    const char *at = text ? strstr(text, after) : NULL;
    size_t n = 0;
    *name = 0;
    if (!at) return NULL;
    at += strlen(after);
    while (at[n] && at[n] != ' ' && at[n] != ';' && at[n] != ':' && at[n] != '\n' && at[n] != '\r' && n + 1 < capacity) n++;
    memcpy(name, at, n); name[n] = 0;
    return at;
}
static void test_input_exposures(void)
{
    admission_fixture f; lease_collection_setup(&f);
    sh_decl_registry_source registry = {&f, admission_read, (uintptr_t)f.registry, NULL};
    char data[MAX_PATH], kept[96] = "", left[96] = "", stand[96] = "", line[256], *text;
    snprintf(data, sizeof(data), "%s/input-exposures", root);
    create("input-exposures/overrides/lamp-a/package.json", "{\"id\":\"lamp-a\",\"name\":\"Lamp A\"}");
    create("input-exposures/overrides/lamp-a/assets/generated/decls/snapeditorentitydef/inlinestock/base_row.decl",
        "{\n\tinherit = \"inlinestock/row_base\";\n\tedit = {\n\t\tentityDef = \"inlinestock/base\";\n"
        "\t\tdisplayNameTag = \"#str_lamp_a\";\n\t}\n}\n");
    create("input-exposures/overrides/lamp-b/package.json", "{\"id\":\"lamp-b\",\"name\":\"Lamp B\"}");
    create("input-exposures/overrides/lamp-b/assets/generated/decls/snapeditorentitydef/inlinestock/base_row.decl",
        "{\n\tinherit = \"inlinestock/row_base\";\n\tedit = {\n\t\tentityDef = \"inlinestock/base\";\n"
        "\t\tdisplayNameTag = \"#str_lamp_b\";\n\t}\n}\n");
    create("input-exposures/overrides/tough/package.json", "{\"id\":\"tough\",\"name\":\"Tough\"}");
    create("input-exposures/overrides/tough/assets/generated/decls/entitydef/inline/tough_parent.decl",
        "{ inherit = \"inlinestock/base\"; edit = { health = 30; } }");
    create("input-exposures/overrides/tough/assets/generated/decls/entitydef/inline/tough.decl",
        "{ inherit = \"inline/tough_parent\"; edit = { health = 40; } }");
    create("input-exposures/overrides/tough/assets/generated/decls/snapeditorentitydef/inline/tough_row.decl",
        "{ inherit = \"inlinestock/base_row\"; edit = { entityDef = \"inline/tough\"; } }");
    create("input-exposures/overrides/tough/assets/generated/decls/snapeditorentitydef/inline/tough_row2.decl",
        "{ inherit = \"inlinestock/base_row\"; edit = { entityDef = \"inline/tough\"; displayNameTag = \"#str_tough_two\"; } }");
    sh_package_runtime_test_dispose(); sh_package_runtime_test_baseline(library_baseline, NULL);
    sh_package_runtime_test_source_readers(registry, (uintptr_t)f.reflection);
    sh_package_runtime_test_installed_links(1);
    sh_package_runtime_test_editor_rows(library_editor_rows, sizeof(library_editor_rows) / sizeof(*library_editor_rows));
    CHECK(sh_package_runtime_refresh(data)); CHECK(sh_package_runtime_ready());
    text = sh_package_runtime_inputs(NULL, 1);
    fprintf(stderr, "input exposures overview:\n%s\n", text ? text : "(null)");
    CHECK(text && input_line(text, "Equal exposures: 1 set keeps one editor row each in the pickers; 2 other rows "
        "left out of them stay served and registered.", NULL));
    free(text);
    text = sh_package_runtime_inputs("lamp-a", 1);
    fprintf(stderr, "input exposures lamp-a:\n%s\n", text ? text : "(null)");
    input_row_name(text, "; editor row ", kept, sizeof(kept));
    CHECK(text && *kept && !strncmp(kept, "smp/", 4) &&
        input_line(text, "base_row.decl | ", "served: row generated/decls/snapeditorentitydef/smp/"));
    snprintf(line, sizeof(line), "editor row %s kept in the pickers for an equal exposure of 3 rows", kept);
    CHECK(text && input_line(text, "base_row.decl | ", line));
    free(text);
    text = sh_package_runtime_inputs("lamp-b", 1);
    fprintf(stderr, "input exposures lamp-b:\n%s\n", text ? text : "(null)");
    input_row_name(text, "; editor row ", left, sizeof(left));
    snprintf(line, sizeof(line), "editor row %s left out of the pickers for an equal exposure (still served and "
        "registered): %s of Lamp A [lamp-a] is kept for it, as its package comes earlier in library order", left, kept);
    CHECK(text && *left && strcmp(left, kept) && input_line(text, "base_row.decl | ", "served: row ") &&
        input_line(text, "base_row.decl | ", line));
    free(text);
    /* The steer's stand-in: the shipped row and the other variant both name the kept row. */
    CHECK(sh_package_runtime_exposure_kept("inlinestock/base_row", stand, sizeof(stand)) == 1 && !strcmp(stand, kept));
    CHECK(sh_package_runtime_exposure_kept(left, stand, sizeof(stand)) == 1 && !strcmp(stand, kept));
    CHECK(!sh_package_runtime_exposure_kept(kept, stand, sizeof(stand)));
    /* Every exposure line: the kept row stands for the shipped row and the other variant. */
    text = sh_package_runtime_input_exposures("lamp-a", 6, 1);
    fprintf(stderr, "input exposures lamp-a entry:\n%s\n", text ? text : "(null)");
    snprintf(line, sizeof(line), "kept in the pickers for an equal exposure of 3 rows, standing for inlinestock/base_row, "
        "%s of Lamp B [lamp-b]", left);
    CHECK(text && input_line(text, ". editor row generated/decls/snapeditorentitydef/smp/", line));
    free(text);
    /* An input reached through an editor row that no equal exposure touches. */
    text = sh_package_runtime_inputs("assets/generated/decls/entitydef/inline/tough.decl", 1);
    fprintf(stderr, "input exposures tough:\n%s\n", text ? text : "(null)");
    CHECK(text && input_line(text, "tough.decl | ", "served: row ") && input_line(text, "tough.decl | ", "; editor row smp/") &&
        input_line(text, "tough.decl | ", " (private alias of generated/decls/snapeditorentitydef/inline/tough_row.decl)") &&
        !strstr(text, "pickers"));
    free(text);
    /* Two steps away: both rows reach the parent their entityDef inherits. */
    text = sh_package_runtime_inputs("assets/generated/decls/entitydef/inline/tough_parent.decl", 1);
    fprintf(stderr, "input exposures tough_parent:\n%s\n", text ? text : "(null)");
    CHECK(text && input_line(text, "tough_parent.decl | ", "served: row ") &&
        input_line(text, "tough_parent.decl | ", " (private alias of generated/decls/snapeditorentitydef/inline/tough_row.decl)") &&
        input_line(text, "tough_parent.decl | ", " (private alias of generated/decls/snapeditorentitydef/inline/tough_row2.decl)"));
    free(text);
    /* Another row placing that entityDef never reaches this row's own file through the entityDef's lifetime
     * edge to the rows describing it. */
    text = sh_package_runtime_inputs("assets/generated/decls/snapeditorentitydef/inline/tough_row2.decl", 1);
    fprintf(stderr, "input exposures tough_row2:\n%s\n", text ? text : "(null)");
    CHECK(text && input_line(text, "tough_row2.decl | ", "served: row ") && !strstr(text, "; editor row"));
    free(text);
    sh_package_runtime_test_editor_rows(NULL, 0);
    sh_package_runtime_test_installed_links(0);
    sh_package_runtime_test_source_readers((sh_decl_registry_source){0}, 0); sh_package_runtime_test_dispose();
    sh_package_runtime_test_baseline(baseline, NULL);
    for (size_t i = 0; i < f.count; i++) free(f.regions[i].address);
    cleanup_resources(data);
}
