    CHECK(text && input_line(text, "ind_totally_blank_room_4x.baas_monster48 | ", "served: row ") &&
        input_line(text, "ind_totally_blank_room_4x.baas_monster48 | ", "; read by generated " GRID_NAV_OUTPUT " as aas ") &&
        !strstr(text, "private alias of " GRID_NAV_OUTPUT));
    CHECK(text && input_line(text, "864_272_432.baas_monster48 | ", "served: row " GRID_NAV_OUTPUT
        " as aas maps/modules/smpgrid/v1/m/864_272_432/864_272_432.aas_monster48 (generated)"));
    free(text);
    sh_package_runtime_test_installed_links(0);
    sh_package_runtime_test_source_readers((sh_decl_registry_source){0}, 0); sh_package_runtime_test_dispose();
    sh_package_runtime_test_baseline(baseline, NULL);
    for (size_t i = 0; i < f.count; i++) free(f.regions[i].address);
    free(produced); free(grid_nav_stock); grid_nav_stock = NULL; grid_nav_stock_length = 0;
    cleanup_resources(data);
