/* A typed pointer to a declaration only the campaign archive carries, in stock
 * text that no package text inherits, is the stock route's own reference: the
 * package is served (route). A package that supplies the declaration binds to
 * its own file (supplied). Package text that inherits that stock text through
 * a layer reached after the stock declaration was read still refuses (late):
 * the inheritance makes the reference authored when it arrives. */
static int campaign_stock_route_baseline(void *context, const char *path, unsigned char **body, size_t *length)
{
    const char *text = !strcmp(path, "generated/decls/entitydef/admission/stockpointer2.decl") ||
            !strcmp(path, "generated/decls/entitydef/admission/stockpointer3.decl") ?
            "{ class = \"Entity\"; edit = { health = 1; target = \"ai/cyberdemon\"; } }" :
        !strcmp(path, "generated/decls/entitydef/admission/layer_m.decl") ?
            "{ inherit = \"admission/layer_l\"; edit = { health = 2; } }" :
        !strcmp(path, "generated/decls/entitydef/admission/layer_l.decl") ?
            "{ inherit = \"admission/stockpointer3\"; edit = { health = 3; } }" : NULL;
    if (!text) return baseline(context, path, body, length);
    *body = (unsigned char *)_strdup(text);
    *length = *body ? strlen((const char *)*body) : 0;
    return *body ? 1 : -1;
}
