/* Offline stand-in for the engine's written-state comparison (plumbing
 * only). It answers g_native_status (EQUAL by default) for every definition
 * pair the runtime submits and records the route: these runtime assertions
 * cover binding, per-definition source authority, the private preparation of
 * document-only chains and ownership recomputation after each verdict; native
 * equality itself is proved only by paired controls. */
static int g_native_compares;
static sh_native_eval_status g_native_status = SH_NATIVE_EVAL_EQUAL;
static size_t g_native_layers;
static char g_native_layer[256], g_native_layer_text[512];
static char g_native_chain[1024];
static char g_native_chain_text[2048];
/* R-212 stand-in for the engine's prepared texts where they are each
 * definition's own edit block: a stateless stock base, one private layer and
 * an empty instance. The production reduction then runs on both texts and an
 * exact comparison decides; extra is added to the target's block only. */
static int g_native_prepared;
static const char *g_native_prepared_extra = "";
static size_t g_native_reduced;
/* A prepared state stand-in in the engine's shape: the merged tree's
 * top-level statements, with no enclosing braces (VK 0x1417ae9d0 prints them
 * through VK 0x141a670d0, R-295). */
static char *test_prepared(const char *definition, const char *extra)
{
    const char *at = definition ? strstr(definition, "edit = {") : NULL, *end;
    int depth = 0;
    if (!at) return NULL;
    at += 7;
    for (end = at; *end; end++) if ((*end == '{' && ++depth) || (*end == '}' && !--depth)) { if (!depth) break; }
    if (!*end) return NULL;
    size_t length = (size_t)(end - at) + strlen(extra) + 16;
    char *text = malloc(length);
    if (text) snprintf(text, length, "edit = %.*s%s}\n", (int)(end - at), at, extra);
    return text;
}
/* A stand-in's statements as the members of one block. */
static sh_decl_node *test_prepared_tree(const char *text, char *error, size_t capacity)
{
    size_t length = strlen(text);
    char *braced = malloc(length + 4);
    sh_decl_node *tree = NULL;
    if (braced) {
        snprintf(braced, length + 4, "{%s\n}", text);
        tree = sh_decl_tree_parse_ordered((sh_decl_source){braced, strlen(braced)}, error, capacity);
        free(braced);
    }
    return tree;
}
static sh_native_eval_status test_prepared_compare(const sh_native_eval_layer *layers, size_t layer_count,
    const char *target, const char *candidate, const sh_native_eval_reduction *reduction, char *detail, size_t capacity)
{
    sh_native_eval_status status = SH_NATIVE_EVAL_UNSUPPORTED;
    char *t = layer_count == 1 ? test_prepared(layers[0].text, g_native_prepared_extra) : NULL;
    /* With no private layer the engine serves the target's parent: its served text. */
    const char *named = !layer_count && target ? strstr(target, "inherit = \"") : NULL;
    if (named) {
        char path[400]; unsigned char *body = NULL; size_t body_length = 0; const char *end = strchr(named + 11, '"');
        snprintf(path, sizeof(path), "generated/decls/entitydef/%.*s.decl", end ? (int)(end - named - 11) : 0, named + 11);
        if (end && sh_package_runtime_read(path, &body, &body_length) == 1 && body) {
            char *text = malloc(body_length + 1);
            if (text) { memcpy(text, body, body_length); text[body_length] = 0; t = test_prepared(text, g_native_prepared_extra); free(text); }
        }
        free(body);
    }
    char *c = test_prepared(candidate, ""), *rt = NULL, *rc = NULL, why[200] = "";
    size_t tl = 0, cl = 0;
    if (!t || !c) snprintf(detail, capacity, "prepared stand-in unavailable (%zu layers, %d %d: %.60s | %.60s)", layer_count, !t, !c, layer_count ? layers[0].text : "", candidate);
    else if (strcmp(t, c) && !reduction) snprintf(detail, capacity, "the prepared states differ");
    else if (strcmp(t, c) && (reduction->reduce(reduction->context, t, strlen(t), &rt, &tl, &g_native_reduced, why, sizeof(why)) != 1 ||
        reduction->reduce(reduction->context, c, strlen(c), &rc, &cl, &g_native_reduced, why, sizeof(why)) != 1))
        snprintf(detail, capacity, "outside the proof: %s", why);
    else if (strcmp(t, c) && (tl != cl || memcmp(rt, rc, tl))) snprintf(detail, capacity, "the prepared states differ outside the proved reduction");
    else status = SH_NATIVE_EVAL_EQUAL;
    free(t); free(c); free(rt); free(rc);
    return status;
}
/* Holder-substitution stand-in: the engine merges the private layer's edit
 * block over the stock base and compares the prepared states after the
 * caller's reduction. Here the states agree when every member of the reduced
 * layer restates the stock base's own member of that name, so a layer still
 * naming a served definition, or changing any other value, differs. */
static int test_nodes_same(const sh_decl_node *a, const sh_decl_node *b);
static int test_node_same(const sh_decl_node *a, const sh_decl_node *b)
{
    return a->compound == b->compound && !strcmp(a->key ? a->key : "", b->key ? b->key : "") &&
        !strcmp(a->value ? a->value : "", b->value ? b->value : "") && test_nodes_same(a->children, b->children);
}
static int test_nodes_same(const sh_decl_node *a, const sh_decl_node *b)
{
    for (; a && b; a = a->next, b = b->next) if (!test_node_same(a, b)) return 0;
    return !a && !b;
}
static const sh_decl_node *test_edit_block(const sh_decl_node *tree)
{
    for (const sh_decl_node *member = tree ? tree->children : NULL; member; member = member->next)
        if (member->compound && member->key && !strcmp(member->key, "edit")) return member;
    return NULL;
}
static sh_native_eval_status test_sigma_compare(const sh_native_eval_layer *layers, size_t layer_count,
    const char *candidate, const sh_native_eval_reduction *reduction, char *detail, size_t capacity)
{
    sh_native_eval_status status = SH_NATIVE_EVAL_UNSUPPORTED;
    const char *named = strstr(candidate, "inherit = \""), *end = named ? strchr(named + 11, '"') : NULL;
    char path[400], why[200] = "", error[160] = "", *t = layer_count == 1 ? test_prepared(layers[0].text, "") : NULL,
        *s = NULL, *rt = NULL;
    unsigned char *body = NULL;
    size_t body_length = 0, tl = 0, removed = 0;
    if (end) {
        snprintf(path, sizeof(path), "generated/decls/entitydef/%.*s.decl", (int)(end - named - 11), named + 11);
        if (inline_baseline(NULL, path, &body, &body_length) == 1 && body) s = test_prepared((const char *)body, "");
    }
    if (!t || !s) snprintf(detail, capacity, "prepared stand-in unavailable (%zu layers)", layer_count);
    else if (reduction && reduction->reduce(reduction->context, t, strlen(t), &rt, &tl, &removed, why, sizeof(why)) != 1)
        snprintf(detail, capacity, "outside the proof: %s", why);
    else {
        /* A reduced text is the canonical writer's braced block. */
        sh_decl_node *layer = rt ? sh_decl_tree_parse_ordered((sh_decl_source){rt, tl}, error, sizeof(error)) :
            test_prepared_tree(t, error, sizeof(error));
        sh_decl_node *stock = test_prepared_tree(s, error, sizeof(error));
        const sh_decl_node *own = test_edit_block(layer), *native = test_edit_block(stock), *member = own ? own->children : NULL;
        for (; member; member = member->next) {
            const sh_decl_node *same = native ? native->children : NULL;
            while (same && strcmp(same->key ? same->key : "", member->key ? member->key : "")) same = same->next;
            if (!same || !test_node_same(member, same)) break;
        }
        if (!own || !native) snprintf(detail, capacity, "prepared stand-in does not parse: %s", error);
        else if (member) snprintf(detail, capacity, "the prepared states differ at '%s'", member->key ? member->key : "?");
        else status = SH_NATIVE_EVAL_EQUAL;
        sh_decl_tree_free(layer); sh_decl_tree_free(stock);
    }
    free(t); free(s); free(rt); free(body);
    return status;
}
static sh_native_eval_status test_native_compare(const sh_native_eval_layer *layers, size_t layer_count,
    const char *target, const char *candidate, const sh_native_eval_reduction *reduction, char *detail, size_t capacity)
{
    g_native_compares++;
    if (g_native_fail_at && g_native_compares == g_native_fail_at) return SH_NATIVE_EVAL_UNSUPPORTED;
    g_native_layers = layer_count;
    snprintf(g_native_layer, sizeof(g_native_layer), "%s", layer_count && layers[0].name ? layers[0].name : "");
    snprintf(g_native_layer_text, sizeof(g_native_layer_text), "%s", layer_count && layers[0].text ? layers[0].text : "");
    g_native_chain[0] = g_native_chain_text[0] = 0;
    for (size_t i = 0; i < layer_count; i++) {
        size_t used = strlen(g_native_chain);
        snprintf(g_native_chain + used, sizeof(g_native_chain) - used, "%s%s", i ? "|" : "", layers[i].name ? layers[i].name : "?");
        used = strlen(g_native_chain_text);
        snprintf(g_native_chain_text + used, sizeof(g_native_chain_text) - used, "%s%s", i ? "|" : "", layers[i].text ? layers[i].text : "?");
    }
    if (!target || !candidate || !strstr(target, "inherit") || !strstr(candidate, "inherit")) return SH_NATIVE_EVAL_FAILED;
    if (g_native_prepared == 2) return test_sigma_compare(layers, layer_count, candidate, reduction, detail, capacity);
    if (g_native_prepared) return test_prepared_compare(layers, layer_count, target, candidate, reduction, detail, capacity);
    if (g_native_status != SH_NATIVE_EVAL_EQUAL) snprintf(detail, capacity, "stand-in verdict %d", (int)g_native_status);
    return g_native_status;
}

/* ---- Warm publication (R-344 stage B) ----------------------------------------------------------------------
 * A start compile writes its publication as a record; a later start with the same inputs (a disposed runtime
 * stands for a new process) loads it without compiling, and its published library, inventory and history equal
 * the cold one byte for byte (sh_package_runtime_test_publication_text). Changed inputs, changed native answers
 * and damaged records are misses that compile cold in the same start; exhausted memory releases every staged
 * object first. Test doubles answer here; real native revalidation is not exercised by these fixtures. */
#include "package_virtual_page_source.h"
#include "package_native_assets.h"
typedef struct warm_snapshot { char *text; size_t length; long compiles, hits, misses, writes; char last[512]; } warm_snapshot;
static void warm_take(warm_snapshot *s)
{
    free(s->text); s->text = sh_package_runtime_test_publication_text(&s->length); CHECK(s->text != NULL);
    s->compiles = sh_package_runtime_test_compiles();
    sh_package_runtime_test_warm_counts(&s->hits, &s->misses, &s->writes, s->last, sizeof(s->last));
}
static void warm_counts_now(warm_snapshot *s)
{
    s->compiles = sh_package_runtime_test_compiles();
    sh_package_runtime_test_warm_counts(&s->hits, &s->misses, &s->writes, s->last, sizeof(s->last));
}
static int warm_equal(const warm_snapshot *a, const warm_snapshot *b, const char *label)
{
    int same = a->text && b->text && a->length == b->length && !memcmp(a->text, b->text, a->length);
    if (!same && a->text && b->text) {
        size_t at = 0, n = a->length < b->length ? a->length : b->length;
        while (at < n && a->text[at] == b->text[at]) at++;
        size_t from = at > 120 ? at - 120 : 0;
        fprintf(stderr, "%s: publications differ at byte %zu of %zu/%zu\n  cold: %.300s\n  warm: %.300s\n", label, at,
            a->length, b->length, a->text + from, b->text + from);
    }
    return same;
}
static void warm_free(warm_snapshot *s) { free(s->text); memset(s, 0, sizeof(*s)); }
static const char *warm_find(const warm_snapshot *s, const char *needle)
{
    size_t n = strlen(needle);
    for (size_t at = 0; s->text && n && at + n <= s->length; at++) if (!memcmp(s->text + at, needle, n)) return s->text + at;
    return NULL;
}
static int warm_last(const char *wanted)
{
    long hits, misses, writes; char last[512];
    sh_package_runtime_test_warm_counts(&hits, &misses, &writes, last, sizeof(last));
    if (!strstr(last, wanted)) fprintf(stderr, "warm: expected \"%s\", last: %s\n", wanted, last);
    return strstr(last, wanted) != NULL;
}
static int warm_missed(const char *wanted)
{
    char miss[512];
    sh_package_runtime_test_warm_miss(miss, sizeof(miss));
    if (!strstr(miss, wanted)) fprintf(stderr, "warm: expected a miss \"%s\", last miss: %s\n", wanted, miss);
    return strstr(miss, wanted) != NULL;
}
/* The rich library: localized strings, constructor consumers, private virtual pages, an authored bank and sound. */
static int warm_page_absent(void *context, const char *path, sh_package_file **file, char *error, size_t capacity)
{ (void)context; (void)path; (void)error; (void)capacity; *file = NULL; return 0; }
static unsigned warm_atlas_calls;
static int warm_atlas_original; /* 1: answer as if the scope's pages were the original ones */
static int warm_atlas(void *context, size_t scope, const sh_package_compilation *compiled, const char *material,
    const char *page_file, sh_package_virtual_atlas *out, char *error, size_t capacity)
{
    (void)context; (void)scope; (void)material;
    warm_atlas_calls++;
    memset(out, 0, sizeof(*out));
    out->name = "_vmtr"; out->source = "virtualtextures/_vmtr"; out->original = 1;
    if (!compiled || !page_file || *page_file) return -1;
    if (!warm_atlas_original && sh_package_compilation_find(compiled, "virtualtextures/_vmtr_sq1.mega2")) {
        out->pages = sh_virtual_page_source_open(compiled, "virtualtextures/_vmtr", warm_page_absent, NULL, error, capacity);
        if (!out->pages) return -1;
        out->source = "virtualtextures/_vmtr.pages"; out->original = 0; out->page_kind = 2; out->page_mode = 2;
        memcpy(out->content, sh_virtual_page_source_identity(out->pages), 32);
    }
    return 1;
}
static const char warm_prog_parameter[] = "{ Tex2D textures/source }";
static movie_lease_bytes warm_movie;
static int warm_color_changed, warm_dlc_present, warm_atlas_changed;
static int warm_backing = 1; /* the test baseline's answers carry a backing (sh_package_runtime_test_baseline_backing) */
static int warm_baseline(void *context, const char *path, unsigned char **body, size_t *length)
{
    const char *text = NULL;
    (void)context;
    if (!strcmp(path, "virtualtextures/_vmtr.vmtr")) text = "26\n1\n8 4 16 16 0 1 2 \"surfaces/stone\"\n";
    else if (warm_dlc_present && !strcmp(path, "virtualtextures/_vmtr_dlc1.vmtr")) text = "26\n0\n";
    else if (warm_color_changed && !strcmp(path, "generated/decls/renderparm/color.decl")) text = "{ Vec 1 }";
    else if (warm_atlas_changed && !strcmp(path, "generated/swf/stock/panel.bimage")) text = "stock atlas pixelz"; /* equal length */
    else if (!strcmp(path, "generated/image/textures/warm_present.bimage")) text = "warm present image";
    else if (!strcmp(path, "generated/decls/renderparm/tex.decl")) text = warm_prog_parameter; /* native ABI: original */
    if (!text) return movie_lease_baseline(&warm_movie, path, body, length);
    *length = strlen(text); *body = (unsigned char *)_strdup(text); CHECK(*body);
    return *body ? 1 : -1;
}
/* Image availability: both referenced images answer usable; the flip answers the installed one excluded. */
static int warm_image_flip;
static unsigned warm_image_present, warm_image_absent;
static int warm_image_excluded(void *context, const char *name, const unsigned char *installed, size_t length)
{
    (void)context;
    if (!strcmp(name, "textures/warm_present")) {
        CHECK(installed && length == 18 && !memcmp(installed, "warm present image", 18));
        warm_image_present++;
        return warm_image_flip;
    }
    if (!strcmp(name, "textures/warm_absent")) { CHECK(!installed && !length); warm_image_absent++; }
    return 0;
}
#include "decl_material.h"
