/* Shader ABI facts: the parameter tex (a renderparm whose original the baseline serves) at its declared kind and a
 * fixed index; the flip moves the index. The compile asks it through sh_package_runtime_test_shader_questions:
 * fixtures without native semantics cannot link a renderprog whose references would ask it. */
static int warm_shader_flip;
static unsigned warm_shader_calls;
static int warm_shader_parameter(void *context, const char *name, sh_decl_source source, int *kind, uint32_t *index,
    char *error, size_t capacity)
{
    int declared = -1;
    (void)context;
    warm_shader_calls++;
    if (strcmp(name, "tex") || !source.text || source.length != strlen(warm_prog_parameter) ||
        memcmp(source.text, warm_prog_parameter, source.length) ||
        !sh_decl_material_parameter_kind(source, &declared, error, capacity) || declared < 0) return 0;
    *kind = declared; *index = 17u + (warm_shader_flip ? 1u : 0u);
    return 1;
}
static sh_package_source_shader warm_shader = {SH_PACKAGE_SHADER_VULKAN, NULL, warm_shader_parameter, NULL, NULL};
/* The compile asks these through its adapter (sh_package_runtime_test_shader_questions), twice each. */
static const char *const warm_shader_names[1] = {"tex"};
static const char *const warm_shader_sources[1] = {warm_prog_parameter};
static int warm_reserve_collide; /* the first private key a reservation sees is taken */
static char warm_collided[128];
static int warm_reserve(void *context, const char *key, const unsigned char identity[32], const char *mapping)
{
    (void)context; (void)identity;
    CHECK(key && mapping);
    if (warm_reserve_collide && (!warm_collided[0] || !strcmp(warm_collided, key))) {
        if (!warm_collided[0]) snprintf(warm_collided, sizeof(warm_collided), "%s", key);
        return 0;
    }
    return 1;
}
static void warm_rich_files(void)
{
    unsigned char mega2[0x199];
    char path[MAX_PATH];
    create("warm-rich/overrides/outer/package.json", "{\"id\":\"warm-outer\",\"name\":\"Warm outer\","
        "\"strings\":{\"english\":{\"notice\":\"warm\"},\"french\":{\"notice\":\"chaud\"}}}");
    /* A scope opening the image gate asks availability of the images its units reference. */
    create("warm-rich/overrides/gated/package.json", "{\"id\":\"warm-gated\",\"name\":\"Warm gated\","
        "\"requirements\":{\"cvars\":{\"g_useImageBlackList\":0}}}");
    create("warm-rich/overrides/gated/assets/generated/decls/material/warm/present.decl", "{ tex \"textures/warm_present\" }");
    create("warm-rich/overrides/gated/assets/generated/decls/material/warm/absent.decl", "{ tex \"textures/warm_absent\" }");
    /* The package supplies this image; no installed one exists, so its question carries no installed bytes. */
    create("warm-rich/overrides/gated/assets/generated/image/textures/warm_absent.bimage", "package image bytes");
    create("warm-rich/overrides/outer/assets/generated/decls/material/late/fx.decl", "{ color {1,0,0} }");
    create("warm-rich/overrides/outer/assets/generated/decls/sound/play_computed.decl", "{ edit = {} }");
    write_bank("warm-rich/overrides/outer/assets/sound/soundbanks/pc/warm_a.bnk", "warm_a.bnk", 1984956495u);
    create("warm-rich/overrides/outer/selected/package.json", "{\"id\":\"warm-selected\",\"name\":\"Warm selected\","
        "\"strings\":{\"english\":{\"notice\":\"selected\",\"empty\":\"\"}}}");
    create("warm-rich/overrides/outer/selected/assets/generated/decls/entitydef/movie/screen.decl",
        "{ class = \"Entity\"; edit = { gui = \"swf/stock/panel.swf\"; } }");
    create("warm-rich/overrides/consumer/package.json", "{\"id\":\"warm-consumer\",\"name\":\"Warm consumer\"}");
    create("warm-rich/overrides/consumer/assets/generated/decls/entitydef/consumer/root.decl",
        "{ class = \"Entity\"; edit = { health = 5; } }");
    create("warm-rich/overrides/consumer/assets/generated/decls/entitydef/consumer/leaf.decl",
        "{ class = \"Entity\"; edit = { health = 6; } }");
    create("warm-rich/overrides/pages/package.json", "{\"id\":\"warm-pages\",\"name\":\"Warm pages\"}");
    create("warm-rich/overrides/pages/assets/generated/decls/material/surfaces/stone.decl", "{ color {0,1,1} }");
    memset(mega2, 0, sizeof(mega2));
    {
        unsigned char *p = mega2;
#define WARM_PUT(at, value, bytes) do { uint64_t v = (uint64_t)(value); for (unsigned k = 0; k < (bytes); k++) p[(at) + k] = (unsigned char)(v >> (8 * k)); } while (0)
        WARM_PUT(0, 0xa63fbb21u, 4); WARM_PUT(4, 2, 4); WARM_PUT(0xc, 12, 4); WARM_PUT(0x38, 0x170, 8);
        WARM_PUT(0x40, 0x180, 8); WARM_PUT(0x48, 1, 4); WARM_PUT(0x4c, 2, 4); WARM_PUT(0x58, 2, 4);
        WARM_PUT(0x5c, 1, 4); WARM_PUT(0x64, 2, 4); WARM_PUT(0x170, 0x188, 8); WARM_PUT(0x178, 17, 8);
        WARM_PUT(0x184, UINT32_MAX, 4); memset(p + 0x188, 0x3c, 17);
#undef WARM_PUT
    }
    create("warm-rich/overrides/pages/assets/virtualtextures/_vmtr_sq1.mega2", "");
    snprintf(path, sizeof(path), "%s/warm-rich/overrides/pages/assets/virtualtextures/_vmtr_sq1.mega2", root);
    FILE *file = fopen(path, "wb"); CHECK(file != NULL);
    if (file) { CHECK(fwrite(mega2, 1, sizeof(mega2), file) == sizeof(mega2)); fclose(file); }
    create("warm-rich-base/sound/soundbanks/pc", NULL);
    create("warm-rich-hold/extra.decl", "{ class = \"Entity\"; edit = { health = 7; } }");
    write_bank("warm-rich-hold/warm_a.bnk", "warm_a.bnk", 1984956495u); /* an installed bank of the authored name */
}
